    /// <summary>
    /// The logo for an emulator's game, by the console's name as the library shows it: the console's own,
    /// its maker's, or a plain controller for a console with neither.
    /// </summary>
    public static Geometry ForConsole(string? console) =>
        Emulators.Systems.FirstOrDefault(s => s.Name == console) is { } system && Consoles.TryGetValue(system.Id, out var logo)
            ? logo
            : Controller;

    /// <summary>The store's logo, or null for a program the player added. An emulator's game has its console's.</summary>
    public static Geometry? For(GameStore store) => Logos.GetValueOrDefault(store);

    private static Geometry Frozen(string outline)
    {
        // F1 fills the outline the way the SVG it is from does, which is not WPF's own default.
        var geometry = Geometry.Parse("F1 " + outline);
        geometry.Freeze();
        return geometry;
    }
